package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

const versionStr = "v0.0.0\n"

func usage(prog string) string {
	return fmt.Sprintf(`Usage: %s [-][ytjcrneikhv]

Convert between YAML, TOML, JSON, and HCL.
Preserves map order.

-x[x]  Convert using stdin. Valid options:
          -yj, -y = YAML to JSON (default)
          -yy     = YAML to YAML
          -yt     = YAML to TOML
          -yc     = YAML to HCL
          -tj, -t = TOML to JSON
          -ty     = TOML to YAML
          -tt     = TOML to TOML
          -tc     = TOML to HCL
          -jj     = JSON to JSON
          -jy, -r = JSON to YAML
          -jt     = JSON to TOML
          -jc     = JSON to HCL
          -cy     = HCL to YAML
          -ct     = HCL to TOML
          -cj, -c = HCL to JSON
          -cc     = HCL to HCL
-n     Do not covert inf, -inf, and NaN to/from strings (YAML or TOML only)
-e     Escape HTML (JSON out only)
-i     Indent output (JSON or TOML out only)
-k     Attempt to parse keys as objects or numeric types (YAML out only)
-h     Show this help message
-v     Show version

`, prog)
}

func main() {
	prog := os.Args[0]
	args := os.Args[1:]

	// Collect runes in order, skipping ' ', '\t', '-'
	var validRunes []rune
	var invalidRunes []rune
	validSet := map[rune]bool{
		'y': true, 't': true, 'j': true, 'c': true, 'r': true,
		'n': true, 'e': true, 'i': true, 'k': true, 'h': true, 'v': true,
	}
	for _, arg := range args {
		for _, r := range arg {
			if r == ' ' || r == '\t' || r == '-' {
				continue
			}
			if validSet[r] {
				validRunes = append(validRunes, r)
			} else {
				invalidRunes = append(invalidRunes, r)
			}
		}
	}

	if len(invalidRunes) > 0 {
		strs := make([]string, len(invalidRunes))
		for i, r := range invalidRunes {
			strs[i] = string(r)
		}
		msg := usage(prog) + fmt.Sprintf("Error: invalid flags specified: %s\n", strings.Join(strs, " "))
		io.WriteString(os.Stderr, msg)
		os.Exit(1)
	}

	hasH := false
	hasV := false
	for _, r := range validRunes {
		if r == 'h' {
			hasH = true
		}
		if r == 'v' {
			hasV = true
		}
	}
	if hasH {
		io.WriteString(os.Stdout, usage(prog))
		os.Exit(0)
	}
	if hasV {
		io.WriteString(os.Stdout, versionStr)
		os.Exit(0)
	}

	// Determine conversion
	var conv []rune // y,t,j,c after expanding r
	hasN := false
	hasE := false
	hasI := false
	hasK := false
	for _, r := range validRunes {
		switch r {
		case 'r':
			conv = append(conv, 'j', 'y')
		case 'y', 't', 'j', 'c':
			conv = append(conv, r)
		case 'n':
			hasN = true
		case 'e':
			hasE = true
		case 'i':
			hasI = true
		case 'k':
			hasK = true
		}
	}

	var in, out rune
	if len(conv) == 0 {
		in, out = 'y', 'j'
	} else if len(conv) == 1 {
		switch conv[0] {
		case 'y':
			in, out = 'y', 'j'
		case 't':
			in, out = 't', 'j'
		case 'j':
			in, out = 'j', 'j'
		case 'c':
			in, out = 'c', 'j'
		}
	} else {
		in = conv[len(conv)-2]
		out = conv[len(conv)-1]
	}

	// Validate e,i,k (order k,e,i)
	if hasK && out != 'y' {
		msg := usage(prog) + "Error: flag -k only valid for YAML output\n"
		io.WriteString(os.Stderr, msg)
		os.Exit(1)
	}
	if hasE && out != 'j' {
		msg := usage(prog) + "Error: flag -e only valid for JSON output\n"
		io.WriteString(os.Stderr, msg)
		os.Exit(1)
	}
	if hasI && out != 'j' && out != 't' {
		msg := usage(prog) + "Error: flag -i only valid for JSON or TOML output\n"
		io.WriteString(os.Stderr, msg)
		os.Exit(1)
	}

	// Read stdin
	data, err := io.ReadAll(os.Stdin)
	if err != nil {
		// What does original do on read error? Unclear, just exit 1?
		io.WriteString(os.Stderr, fmt.Sprintf("Error reading stdin: %v\n", err))
		os.Exit(1)
	}

	// Convert
	if err := runConvert(in, out, hasN, hasE, hasI, hasK, data); err != nil {
		// runConvert already printed error? Or return error to print?
		// For panics (TOML null), let it panic naturally (don't recover)
		os.Exit(1)
	}
}

