package main

import (
	"fmt"
	"time"

	"gopkg.in/yaml.v3"
)

func parseYAML(data []byte) (Value, error) {
	var doc yaml.Node
	if err := yaml.Unmarshal(data, &doc); err != nil {
		return Value{}, err
	}
	if doc.Kind == 0 || len(doc.Content) == 0 {
		return Value{Kind: EmptyKind}, nil
	}
	return nodeToValue(doc.Content[0])
}

func nodeToValue(n *yaml.Node) (Value, error) {
	if n.Kind == yaml.AliasNode {
		if n.Alias == nil {
			return Value{Kind: NullKind}, nil
		}
		return nodeToValue(n.Alias)
	}
	switch n.Kind {
	case yaml.ScalarNode:
		return scalarNodeToValue(n)
	case yaml.SequenceNode:
		arr := make([]Value, 0, len(n.Content))
		for _, c := range n.Content {
			v, err := nodeToValue(c)
			if err != nil {
				return Value{}, err
			}
			arr = append(arr, v)
		}
		return Value{Kind: ArrayKind, Array: arr}, nil
	case yaml.MappingNode:
		var obj []KV
		for i := 0; i < len(n.Content); i += 2 {
			kNode := n.Content[i]
			vNode := n.Content[i+1]
			kVal, err := nodeToValue(kNode)
			if err != nil {
				return Value{}, err
			}
			vVal, err := nodeToValue(vNode)
			if err != nil {
				return Value{}, err
			}
			obj = append(obj, KV{Key: kVal, Val: vVal})
		}
		return Value{Kind: ObjectKind, Object: obj}, nil
	case yaml.DocumentNode:
		if len(n.Content) == 0 {
			return Value{Kind: EmptyKind}, nil
		}
		return nodeToValue(n.Content[0])
	default:
		return Value{Kind: NullKind}, nil
	}
}

func scalarNodeToValue(n *yaml.Node) (Value, error) {
	switch n.Tag {
	case "!!str":
		var s string
		if err := n.Decode(&s); err != nil {
			return Value{}, fmt.Errorf("scalar decode error: %v", err)
		}
		return Value{Kind: StringKind, Str: s}, nil
	case "!!int":
		var v interface{}
		if err := n.Decode(&v); err != nil {
			return Value{}, fmt.Errorf("scalar decode error: %v", err)
		}
		switch x := v.(type) {
		case int:
			return Value{Kind: IntKind, Int: int64(x)}, nil
		case int64:
			return Value{Kind: IntKind, Int: x}, nil
		case uint64:
			return Value{Kind: UintKind, Uint: x}, nil
		case float64:
			return Value{Kind: FloatKind, Float: x}, nil
		default:
			// fallback
			return Value{}, fmt.Errorf("scalar decode error: unexpected int type %T", v)
		}
	case "!!float":
		var f float64
		if err := n.Decode(&f); err != nil {
			return Value{}, fmt.Errorf("scalar decode error: %v", err)
		}
		return Value{Kind: FloatKind, Float: f}, nil
	case "!!bool":
		var b bool
		if err := n.Decode(&b); err != nil {
			return Value{}, fmt.Errorf("scalar decode error: %v", err)
		}
		return Value{Kind: BoolKind, Bool: b}, nil
	case "!!null":
		return Value{Kind: NullKind}, nil
	case "!!timestamp":
		var t time.Time
		if err := n.Decode(&t); err != nil {
			return Value{}, fmt.Errorf("scalar decode error: %v", err)
		}
		return Value{Kind: TimeKind, Time: t}, nil
	case "!!binary":
		var v interface{}
		if err := n.Decode(&v); err != nil {
			return Value{}, fmt.Errorf("scalar decode error: %v", err)
		}
		switch x := v.(type) {
		case string:
			return Value{Kind: StringKind, Str: x}, nil
		case []byte:
			return Value{Kind: StringKind, Str: string(x)}, nil
		default:
			return Value{Kind: StringKind, Str: fmt.Sprintf("%v", v)}, nil
		}
	default:
		// Unknown tags (e.g., !custom) -> try decode to interface, expect string
		var v interface{}
		if err := n.Decode(&v); err != nil {
			// fallback to raw value as string
			return Value{Kind: StringKind, Str: n.Value}, nil
		}
