	case BoolKind:
		return v.Bool, nil
	case IntKind:
		return v.Int, nil
	case UintKind:
		return v.Uint, nil
	case FloatKind:
		return v.Float, nil
	case StringKind:
		return v.Str, nil
	case ArrayKind:
		arr := make([]interface{}, len(v.Array))
		for i, e := range v.Array {
			conv, err := convertParsedKeyForYAML(e)
			if err != nil {
				return nil, err
			}
			arr[i] = conv
		}
