				return parsedValueToYAMLNode(parsed)
			}
		}
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: s}, nil
	case IntKind, UintKind, BoolKind, NullKind:
		s := stringifyKey(k, hasN)
