package main

import (
	"time"

	"github.com/BurntSushi/toml"
)

func parseTOML(data []byte) (Value, error) {
	var m map[string]interface{}
	md, err := toml.Decode(string(data), &m)
	if err != nil {
		return Value{}, err
	}
	keys := md.Keys()
	// Top-level is always object (even if empty)
	if m == nil {
		m = make(map[string]interface{})
	}
	return tomlMapToValue(m, keys, []string{})
}

func orderedKeysForPrefix(allKeys []toml.Key, prefix []string) []string {
	var ordered []string
	seen := make(map[string]bool)
	for _, k := range allKeys {
		if len(k) <= len(prefix) {
			continue
		}
		match := true
		for i, p := range prefix {
			if k[i] != p {
				match = false
				break
			}
		}
		if !match {
			continue
		}
		next := k[len(prefix)]
		if !seen[next] {
			seen[next] = true
			ordered = append(ordered, next)
		}
	}
	// For top-level with no keys (empty), ordered empty. Good.
	// For nested tables that are implied (like [a.b.c] where a.b not explicit), allKeys may not contain direct prefix?
	// Example: [a.b.c] with d=1, allKeys [a.b.c, a.b.c.d], prefix [] (top-level): next segments are "a" (from both), ordered ["a"]. Good.
	// Prefix ["a"]: Keys with prefix ["a"] are both (len>1), next segments "b" (from both: k[1]="b"), ordered ["b"]. Good.
	// Prefix ["a","b"]: Keys [a.b.c (len3), a.b.c.d (len4)], next segments "c" (k[2]="c"), ordered ["c"]. Good.
	// Prefix ["a","b","c"]: Keys [a.b.c (len3, exact? len==len(prefix)? For exact match, len==len(prefix), skip? Actually for table at prefix ["a","b","c"] (which is table with d), Keys with prefix and len>len(prefix) are [a.b.c.d] (len4), next "d". Good. The exact key a.b.c (len3, equal to prefix) is the table header itself, not a child. Our loop skips len<=len(prefix), so exact match skipped. Good.
	return ordered
}

func tomlMapToValue(m map[string]interface{}, allKeys []toml.Key, prefix []string) (Value, error) {
	ordered := orderedKeysForPrefix(allKeys, prefix)
	// For empty maps with no keys in allKeys? Example: empty TOML (no keys) => ordered empty, return empty object. Good.
	// For maps that are empty due to...? E.g., [a] with no keys? TOML [a] with no keys gives m["a"]=map[] empty, allKeys includes ["a"] (header) but no ["a",...] children. orderedKeysForPrefix with prefix ["a"] will be empty (since no Keys with prefix ["a"] and len>1? Actually Keys has ["a"] exact (len==len(prefix)? For prefix ["a"], len(prefix)=1, Keys ["a"] len=1 <=1, skipped. No other Keys with prefix ["a"], so ordered empty. Good. Return empty object for a. Good.
	// What about maps from inline tables with no keys? Unlikely.
	var obj []KV
	for _, k := range ordered {
		v, ok := m[k]
		if !ok {
			// Should not happen (key in Keys but not in map)? Skip.
			continue
		}
		val, err := tomlValueToOrdered(v, allKeys, append(prefix, k))
		if err != nil {
			return Value{}, err
		}
		obj = append(obj, KV{Key: Value{Kind: StringKind, Str: k}, Val: val})
	}
	// What about keys in m but not in ordered (due to missing in Keys)? Should not happen, but handle: add remaining sorted? Or in map order (random)? Better to add them to avoid data loss.
	// For safety, add any missing keys (from m) not in ordered, in sorted order? Or preserve? Since Keys should contain all, this is fallback.
	// Check: Are there cases where m has keys not in Keys? For empty? No. For...? Possibly for...? Let's just add missing.
	if len(obj) != len(m) {
		// Find missing
		seen := make(map[string]bool)
		for _, kv := range obj {
			seen[kv.Key.Str] = true
		}
		for k, v := range m {
			if !seen[k] {
				val, err := tomlValueToOrdered(v, allKeys, append(prefix, k))
				if err != nil {
					return Value{}, err
				}
				obj = append(obj, KV{Key: Value{Kind: StringKind, Str: k}, Val: val})
			}
		}
	}
	return Value{Kind: ObjectKind, Object: obj}, nil
}

func tomlValueToOrdered(v interface{}, allKeys []toml.Key, prefix []string) (Value, error) {
	switch x := v.(type) {
	case int64:
		return Value{Kind: IntKind, Int: x}, nil
	case uint64:
		return Value{Kind: UintKind, Uint: x}, nil
	case float64:
		return Value{Kind: FloatKind, Float: x}, nil
	case string:
		return Value{Kind: StringKind, Str: x}, nil
	case bool:
		return Value{Kind: BoolKind, Bool: x}, nil
	case time.Time:
		return Value{Kind: TimeKind, Time: x}, nil
	case []interface{}:
		arr := make([]Value, len(x))
		for i, e := range x {
			// For array elements that are maps (tables), need ordered conversion with same prefix?
			// prefix is path to array itself (e.g., ["a"] for a=[[..]]). Elements are at same prefix? Or prefix + index?
			// Keys don't have indices, so use same prefix for all elements (global order).
			// For nested arrays (e.g., [[1,2]]), elements are slices, not maps, no prefix needed.
			vv, err := tomlArrayElementToOrdered(e, allKeys, prefix)
			if err != nil {
				return Value{}, err
			}
			arr[i] = vv
			_ = i
		}
		return Value{Kind: ArrayKind, Array: arr}, nil
	case map[string]interface{}:
		return tomlMapToValue(x, allKeys, prefix)
	case nil:
		return Value{Kind: NullKind}, nil
	default:
		// Handle int (not int64)? BurntSushi gives int64 for ints, but just in case.
		// Also handle float32? No.
		// Fallback: try to handle via reflection? For now, return string?
		return Value{Kind: StringKind, Str: ""}, nil
	}
}

func tomlArrayElementToOrdered(e interface{}, allKeys []toml.Key, prefix []string) (Value, error) {
	switch x := e.(type) {
	case map[string]interface{}:
		return tomlMapToValue(x, allKeys, prefix)
	default:
		return tomlValueToOrdered(e, allKeys, prefix)
	}
}
