// Token parser to Value (with merging, omitting empty lists, etc.)
type hclTokenParser struct {
	toks []hclTok
	pos int
}

func (p *hclTokenParser) peek() hclTok { return p.toks[p.pos] }
func (p *hclTokenParser) next() hclTok {
	t := p.toks[p.pos]
	if p.pos < len(p.toks)-1 {
		p.pos++
	}
	return t
}
func (p *hclTokenParser) atEOF() bool { return p.peek().typ == hEOF }

func (p *hclTokenParser) parseFile() (Value, error) {
	// Top-level ObjectList until EOF
	obj, err := p.parseObjectList(false)
	if err != nil {
		return Value{}, err
	}
